const body = $items('Saweria Webhook')[0].json.body || {};
const message = body.message || '';
const amount = Number(body.amount_raw || 0);
const donatorName = body.donator_name || 'Donatur TMPT';
const donatorEmail = body.donator_email || null;

// Ambil config pricing secara dinamis dari HTTP Request
const pricingConfig = $items('Ambil Pricing JSON')[0].json;
const packages = pricingConfig.packages || {};

const res = packages[amount] || { category: 'donasi', package_name: 'donasi_biasa' };

const emailMatch = message.match(/([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/);
const email = emailMatch ? emailMatch[1] : donatorEmail;

let valid_from = '';
let valid_to = '';
if (res.category === 'membership') {
  const now = new Date();
  valid_from = now.toISOString();
  const exp = new Date();
  exp.setDate(now.getDate() + res.duration_days);
  valid_to = exp.toISOString();
}

return {
  amount: amount,
  email: email,
  category: res.category,
  package_name: res.package_name,
  valid_from: valid_from,
  valid_to: valid_to,
  donor_name: donatorName,
  donator_email: donatorEmail,
  message: message
};

const crypto = require('crypto');

const itemData = $items('Apakah Email Ada?')[0].json;
const keyData = $items('Set Private Key')[0].json;

const plan = itemData.package_name === 'bulanan' ? 'monthly' : 'yearly';

const payload = {
  email: itemData.email,
  plan: plan,
  expires: itemData.valid_to,
  trial: false
};

const payloadString = JSON.stringify(payload);

const payloadB64 = Buffer.from(payloadString)
  .toString('base64')
  .replace(/=/g, '')
  .replace(/\+/g, '-')
  .replace(/\//g, '_');

try {
  const rawJwkSource = keyData.privateKeyJwk || keyData.privateKeyPem || keyData.privateKey;
  if (!rawJwkSource) {
    throw new Error('Kunci privat tidak ditemukan. Pastikan Node "Set Private Key" memiliki field "privateKeyJwk".');
  }

  let rawJwk;
  if (typeof rawJwkSource === 'string') {
    rawJwk = JSON.parse(rawJwkSource);
  } else {
    rawJwk = rawJwkSource;
  }

  if (!rawJwk.d || !rawJwk.x) {
    throw new Error('JWK tidak lengkap. Kunci privat JWK harus memiliki properti "d" dan "x". Properti yang ditemukan: ' + Object.keys(rawJwk).join(', '));
  }

  if (rawJwk.d.includes('GANTI_DENGAN') || rawJwk.d.includes('MASUKKAN') || rawJwk.d.length < 10) {
    throw new Error('Nilai "d" pada JWK masih berupa placeholder atau tidak valid. Harap ganti dengan nilai asli dari tools/license-generator/.keys/private.jwk.json');
  }

  const cleanJwk = {
    kty: rawJwk.kty,
    crv: rawJwk.crv,
    d: rawJwk.d,
    x: rawJwk.x
  };
  const privateKey = crypto.createPrivateKey({
    key: cleanJwk,
    format: 'jwk'
  });

  const sig = crypto.sign(null, Buffer.from(payloadString), privateKey);
  const sigB64 = sig
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');

  const licenseKey = 'TMPT-PRO.' + payloadB64 + '.' + sigB64;

  return {
    license_key: licenseKey,
    email: itemData.email,
    donator_email: itemData.donator_email,
    package_name: itemData.package_name,
    valid_from: itemData.valid_from,
    valid_to: itemData.valid_to,
    donor_name: itemData.donor_name,
    amount: itemData.amount
  };
} catch (err) {
  throw new Error('Gagal generate lisensi Ed25519: ' + err.message);
}

